const KEY='bbj-troubleshooting-v3',M=Model;
let S;try{S=JSON.parse(localStorage.getItem(KEY));if(S?.version!==3)S=M.seed();}catch{S=M.seed();}
let modal=null,pendingFiles=[],lastFocus=null,toastTimer;
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(text,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const tag=(text,color='')=>`<span class="tag ${color}">${esc(text)}</span>`;
const status=x=>tag(M.labels[x]||({effective:'当前有效',superseded:'已替代',approved:'定稿待发布',returned:'已退回',usable:'资料可用',passed:'验收通过',requested:'待管理决策',decided:'待落实',implemented:'已落实',rework:'退回整改',technical:'技术复核',evidence:'待补证据'}[x])||x,['closed','complete','effective','passed','usable','implemented'].includes(x)?'teal':['design','review','lock','revision','approved','technical'].includes(x)?'purple':['triage','pending','rectify','evidence','requested','new','received'].includes(x)?'amber':'');
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch{toast('浏览器空间不足，当前会话可继续，但本次数据未保存。请导出记录。');}}
const menus={pm:[['overview','◫','工作台'],['tasks','▤','施工任务'],['issues','◇','问题与风险'],['drawings','▱','图纸发布'],['acceptance','✓','验收中心'],['surveys','⌁','现场资料'],['risks','⚑','重大事项'],['records','◷','记录与报告']],worker:[['overview','◫','今日'],['tasks','▤','任务'],['issues','◇','问题'],['messages','♧','消息']],designer:[['overview','◫','工作台'],['issues','◇','设计任务'],['drawings','▱','图纸'],['surveys','⌁','实测资料'],['records','◷','处理记录']],chief:[['overview','◫','工作台'],['issues','◇','技术审核'],['drawings','▱','图纸'],['surveys','⌁','实测资料'],['records','◷','审核记录']],boss:[['risks','⚑','重大事项'],['records','◷','项目记录']]};
function nav(page){S.page=page;S.detail=null;S.filter='all';S.search='';render();window.scrollTo(0,0);}
function openDetail(type,id){S.detail={type,id};render();window.scrollTo(0,0);}
function head(eyebrow,title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="subtitle">${subtitle}</div></div><div class="actions">${actions}</div></div>`;}
function card(title,body,extra=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${extra}</div>${body}</section>`;}
function empty(title='暂无待办',sub='新的业务事项会自动出现在这里。'){return `<div class="empty"><strong>${title}</strong>${sub}</div>`;}
function stat(label,n,note){return `<div class="stat"><div class="statlabel">${label}</div><div class="statnum">${n}<small>项</small></div><div class="statnote">${note}</div></div>`;}
function facts(items){return `<div class="factgrid">${items.map(([l,v])=>`<div class="fact"><label>${l}</label><div>${v}</div></div>`).join('')}</div>`;}
function files(fs){return fs?.length?`<div class="filelist">${fs.map(f=>`<a class="file" href="${f.data}" target="_blank" rel="noopener" download="${esc(f.name)}">${f.image?`<img src="${f.data}" alt="${esc(f.name)}">`:''}↗ ${esc(f.name)}</a>`).join('')}</div>`:'<p class="quiet">未附文件 · 示例初始记录</p>';}
function timeline(object){const rows=S.audit.filter(x=>!object||x.object===object);return `<div class="cardbody">${rows.slice(0,12).map(x=>`<div class="event">${esc(x.text)}<small>${esc(x.actor)} · ${esc(x.time)}</small></div>`).join('')||'<span class="quiet">后续操作将在这里留痕</span>'}</div>`;}
function queue(title,meta,action,id,icon='◇',badges=''){return `<div class="queueitem"><div class="queueicon">${icon}</div><div class="body">${badges}<div class="itemtitle">${esc(title)}</div><div class="itemmeta">${esc(meta)}</div></div>${b('查看 →',action,id,'small')}</div>`;}
function roleIssues(){return S.issues.filter(i=>S.role==='designer'||S.role==='chief'?i.path==='design':true);}
function issueActions(i){let r='';if(S.role==='pm'&&['triage','supplement'].includes(i.status))r+=b('研判与分流','triage',i.id,'primary');if(S.role==='pm'&&i.status==='lock')r+=b('现场核对与发布','publish',i.id,'primary');if(S.role==='worker'&&i.status==='supplement')r+=b('补充问题卡说明','supplement',i.id,'primary');if(S.role==='worker'&&['rectify','evidence'].includes(i.status))r+=b(i.status==='evidence'?'补充证据并重提':'提交整改并申请验收','rectify',i.id,'primary');if(S.role==='designer'&&['design','revision'].includes(i.status))r+=b('提交设计成果','design',i.id,'primary')+b('请求补测','requestSurvey',i.id);if(S.role==='chief'&&i.status==='review')r+=b('技术审核','review',i.id,'primary');if(i.status==='pending'){const a=S.acceptances.find(x=>x.target===i.id&&x.status==='pending');if(a)r+=b(S.role==='pm'?'进入验收中心':'查看验收申请','acceptDetail',a.id,S.role==='pm'?'primary':'');}if(S.role==='pm'&&i.status!=='closed'&&!i.escalation)r+=b('升级重大事项','escalate',i.id);return r;}
function taskActions(t){let r=b('任务详情','taskDetail',t.id);if(S.role==='worker'){if(t.status==='new')r+=b('签收任务','receive',t.id,'primary');if(t.status==='received')r+=b('确认开工条件','start',t.id,'primary');if(t.status==='active'&&!t.impact&&!t.hold)r+=b('记录进展','log',t.id,'primary');}if(S.role==='pm'&&t.impact)r+=b('核对图纸变更影响','updateTask',t.id,'primary');return r;}
function overview(){if(S.role==='boss')return risks();const pending=S.acceptances.filter(a=>a.status==='pending').length,open=S.issues.filter(i=>i.status!=='closed').length;
let qs='';if(S.role==='pm'){S.issues.filter(i=>['triage','lock'].includes(i.status)).forEach(i=>qs+=queue(i.title,i.owner+' · '+M.labels[i.status],'issueDetail',i.id,'◇',status(i.status)));S.acceptances.filter(a=>a.status==='pending').forEach(a=>qs+=queue(a.title,'验收申请 · '+a.owner,'acceptDetail',a.id,'✓',status('pending')));S.surveys.filter(x=>x.status==='pending').forEach(x=>qs+=queue(x.location+' · '+x.point,'现场资料待核验','surveysPage','','⌁'));}else if(S.role==='designer'||S.role==='chief'){const wanted=S.role==='chief'?['review']:['design','revision'];S.issues.filter(i=>wanted.includes(i.status)).forEach(i=>qs+=queue(i.title,i.location+' · '+i.due,'issueDetail',i.id,'▱',status(i.status)));}else{S.tasks.filter(t=>!['complete','pending'].includes(t.status)).forEach(t=>qs+=queue(t.title,t.location,'taskDetail',t.id,'▤',status(t.status)));S.issues.filter(i=>['rectify','evidence','supplement'].includes(i.status)).forEach(i=>qs+=queue(i.title,M.labels[i.status]+' · '+i.due,'issueDetail',i.id,'◇'));}
const worker=S.role==='worker';return head('WORKSPACE / '+(worker?'FIELD':'PROJECT'),'把现场问题，逐项解决。',worker?'王班长，今天从当前任务开始。':'滨江商务中心 T2 · 东立面幕墙试点',worker?b('＋ 现场采集','survey'):b('＋ 派发任务','dispatch')+b('上报问题','report'))+
(!worker?`<div class="guide"><div><strong>三条路径，一个工作现场</strong><p>正常施工直接执行；普通问题直接整改；需要改图时再进入设计审核。</p></div>${b('查看业务路径','guide','','small')}</div>`:'')+
`<div class="stats">${stat(worker?'执行中任务':'在执行任务',S.tasks.filter(t=>t.status==='active').length,'当前试点范围')}${stat('待处理问题',open,'包含设计与现场处置')}${!worker?stat('待验收',pending,'提交后进入独立验收中心')+stat('重大事项',S.issues.filter(i=>i.escalation&&i.escalation.status!=='implemented').length,'管理决策与技术处置并行'):''}</div>`+
`<div class="${worker?'':'grid'}"><div>${card(worker?'现在需要你处理':'我的待办',qs||empty('当前没有待办理事项','可查看任务与问题的最新进展。'),tag('按当前角色显示'))}${!worker?card('施工任务',S.tasks.slice(0,2).map(t=>queue(t.title,t.location+' · 已完成 '+t.done+'/'+t.planned+' 块','taskDetail',t.id,'▤',status(t.status))).join('')):''}</div>${!worker?`<div>${card('需要关注',`<div class="cardbody"><div class="riskbox"><div class="row">${tag('重大事项','amber')}<span class="quiet">ISS-018</span></div><h3 style="margin-top:10px">E04 节点偏差需设计处置</h3><p>保留原始 18mm 测量事实。批准方案形成前，不作为现场执行指令。</p>${b('查看处置进展','issueDetail','ISS-018','link')}</div><div class="policy">本地交互原型 · 所有项目数据为示例<br>切换角色可继续同一业务记录。</div></div>`)}${card('最近动态',timeline())}</div>`:''}</div>`;}
function tasks(){return head('EXECUTION','施工任务','依据明确，再开始执行。记录、自检与完工申请都在任务内。',S.role==='pm'?b('＋ 派发任务','dispatch'):'')+`<div class="taskcards">${S.tasks.map(t=>{const d=S.drawings.find(x=>x.id===t.drawing);return `<article class="taskcard"><div class="row between"><span class="mono">${esc(t.id)}</span>${status(t.status)}</div><h2>${esc(t.title)}</h2><p>${esc(t.location)}</p><div class="row">${tag(d?.rev||'未绑定','teal')}${tag(t.crew)}</div><p>计划 ${t.planned} 块 · 已完成 ${t.done} 块 · 截止 ${esc(t.due)}</p><div class="progress"><i style="width:${Math.min(100,t.done/t.planned*100)}%"></i></div>${t.impact?'<div class="note dangerNote">图纸已更新，待 PM 核对影响。</div>':''}<div class="actions">${taskActions(t)}</div></article>`;}).join('')}</div>`;}
function issues(){const items=roleIssues().filter(i=>(S.filter==='all'||S.filter==='open'&&i.status!=='closed'||S.filter==='closed'&&i.status==='closed'||S.filter==='design'&&i.path==='design')&&(!S.search||(i.title+i.id+i.location).includes(S.search)));return head('ISSUE MANAGEMENT',S.role==='chief'?'技术审核':S.role==='designer'?'设计任务':'问题与处置','同一问题贯穿研判、设计、整改与验收。',!['chief','boss'].includes(S.role)?b('＋ 上报问题','report'):'')+`<div class="toolbar"><div class="filters">${[['all','全部'],['open','未关闭'],['design','设计处置'],['closed','已关闭']].map(([v,l])=>`<button class="${S.filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><input class="search" id="search" aria-label="搜索问题" placeholder="搜索问题、位置、编号" value="${esc(S.search)}"></div>`+card('问题清单',`<div class="tablewrap"><table><thead><tr><th>问题与位置</th><th>处理路径</th><th>状态</th><th>当前办理人 / 期限</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td class="title"><span class="mono">${esc(i.id)}</span> ${i.level==='major'?tag('重大关注','red'):''}<div class="itemtitle">${esc(i.title)}</div><div class="itemmeta">${esc(i.location)}</div></td><td>${tag(i.path==='design'?'设计处置':i.path==='normal'?'普通整改':'待分流')}</td><td>${status(i.status)}</td><td>${esc(i.owner)}<div class="itemmeta">${esc(i.due||'待明确期限')}</div></td><td>${b('查看 →','issueDetail',i.id,'small')}</td></tr>`).join('')}</tbody></table></div>${!items.length?empty('没有符合条件的问题'):''}`);}
function issueDetail(id){const i=S.issues.find(x=>x.id===id);if(!i)return empty('记录不存在');const d=S.drawings.find(x=>x.id===(i.executionDrawing||i.newDrawing||i.drawing));const stages=i.path==='design'?['PM研判','设计处置','技术审核','现场发布','执行整改','独立验收']:['PM研判','现场整改','独立验收','关闭归档'];let idx=i.path==='design'?({triage:0,supplement:1,design:1,revision:1,review:2,lock:3,rectify:4,evidence:4,pending:5,closed:6}[i.status]??0):({triage:0,supplement:0,rectify:1,evidence:1,pending:2,closed:4}[i.status]??0);
return b('← 返回问题清单','issuesPage','','link detailback')+head('ISSUE / '+esc(i.id),esc(i.title),esc(i.location),status(i.status))+`<div class="steps">${stages.map((x,n)=>`<div class="step ${n<idx?'done':n===idx?'current':''}"><b>${n<idx?'✓':n+1}</b>${x}</div>${n<stages.length-1?'<span class="arrow">›</span>':''}`).join('')}</div><div class="detailgrid"><div>${card('现场事实',`<div class="cardbody"><p class="sectiontext">${esc(i.description)}</p>${files(i.files)}${voiceEvidence(i.voiceDraft)}${facts([['原始依据',esc(S.drawings.find(x=>x.id===i.drawing)?.rev||'现场记录')],['关联任务',esc(i.task||'独立现场问题')]])}</div>`)}${card('处理依据与验收要求',`<div class="cardbody">${facts([['当前办理人',esc(i.owner)],['办理期限',esc(i.due||'待分派')],['处置方案',esc(i.plan||'尚未形成批准执行依据')],['验收要求',esc(i.criteria||'待派工时明确')]])}${i.plan&&['review','lock','revision','design'].includes(i.status)?'<div class="note dangerNote">技术成果尚未完成发布，不作为现场执行指令。</div>':''}${d?`<div class="row" style="margin-top:15px">${tag(d.rev)}${status(d.status)}${b('查看关联图纸','drawingDetail',d.id,'link')}</div>`:''}${i.request?`<div class="note">当前要求：${esc(i.request)}</div>`:''}${i.returnReason?`<div class="note dangerNote">退回要求：${esc(i.returnReason)}</div>`:''}</div><div class="bottomaction">${issueActions(i)||'<span class="quiet">当前角色暂无需操作，可切换相应角色继续办理。</span>'}</div>`)}${i.submissions.length?card('整改提交记录',i.submissions.map(x=>`<div class="cardbody"><div class="quiet">${esc(x.time)}</div><p>${esc(x.text)}</p><p>检查 / 复测：${esc(x.value)}</p>${files(x.files)}</div>`).join('')):''}</div><div>${card('办理记录',timeline(i.id))}${i.escalation?card('重大事项 · 并行跟踪',`<div class="cardbody">${status(i.escalation.status)}<p>${esc(i.escalation.request)}</p>${i.escalation.decision?`<p>管理决定：${esc(i.escalation.decision)}</p>`:''}${b('进入重大事项','risksPage','','link')}<div class="policy">管理决定不代替技术批准和质量验收。</div></div>`):''}</div></div>`;}
function taskDetail(id){const t=S.tasks.find(x=>x.id===id);if(!t)return empty();const d=S.drawings.find(x=>x.id===t.drawing);return b('← 返回任务','tasksPage','','link detailback')+head('TASK / '+esc(t.id),esc(t.title),esc(t.location),status(t.status))+`<div class="detailgrid"><div>${card('任务与施工依据',`<div class="cardbody">${facts([['施工范围',esc(t.scope)],['执行班组',esc(t.crew)],['计划 / 完成',`${t.planned} / ${t.done} 块`],['期限',esc(t.due)]])}<div class="note"><div class="row between"><div>${tag(d?.rev||'未绑定','teal')} ${status(d?.status||'')}</div>${b('查看施工图','drawingDetail',t.drawing,'link')}</div></div><h3>检查与验收要求</h3><p>${esc(t.checks)}</p><div class="quiet">开工条件：${t.start?'已确认交底及本任务要求条件':'待班组签收并确认条件'} · 图纸有效不直接代表全部开工条件满足。</div>${t.impact?`<div class="note dangerNote">${esc(t.impact)}</div>`:''}${t.hold?`<div class="note dangerNote">${esc(t.hold)}</div>`:''}${t.returnReason?`<div class="note dangerNote">验收退回：${esc(t.returnReason)}</div>`:''}</div><div class="bottomaction">${taskActions(t)}${S.role==='worker'&&t.status==='active'&&!t.impact&&!t.hold?b('申请完工验收','taskSubmit',t.id)+b('报问题','report',t.id):''}</div>`)}${card('现场记录',t.records.map(r=>`<div class="cardbody" style="border-bottom:1px solid var(--line)"><div class="row between"><span class="quiet">${esc(r.time)}</span>${tag('完成 +'+r.quantity+' 块')}</div><p>${esc(r.text)}</p>${r.check?tag('自检已记录','teal'):tag('普通进展记录')}${files(r.files)}</div>`).join('')||empty('还没有现场记录'))}</div><div>${card('关联问题',S.issues.filter(i=>i.task===t.id).map(i=>queue(i.title,M.labels[i.status],'issueDetail',i.id)).join('')||empty('没有关联问题'))}${card('任务动态',timeline(t.id))}</div></div>`;}
function drawings(){return head('DRAWING CONTROL','图纸与发布','区分当前有效版本与待审成果。发布不覆盖历史记录。')+card('图纸清单',`<div class="tablewrap"><table><thead><tr><th>图号 / 成果</th><th>修订号</th><th>状态</th><th>适用范围</th><th></th></tr></thead><tbody>${[...S.drawings].reverse().map(d=>`<tr><td class="title"><span class="mono">${esc(d.number)}</span><div class="itemtitle">${esc(d.title)}</div></td><td>${esc(d.rev)}</td><td>${status(d.status)}</td><td>${esc(d.scope)}</td><td>${b('查看','drawingDetail',d.id,'small')}</td></tr>`).join('')}</tbody></table></div>`);}
function drawingDetail(id){const d=S.drawings.find(x=>x.id===id);if(!d)return empty();return b('← 返回图纸','drawingsPage','','link detailback')+head('DRAWING / '+esc(d.number),esc(d.rev)+' · 安装详图',esc(d.scope),status(d.status))+card('图纸预览',`<div class="cardbody"><div class="blueprint"><small>节点示意 · 非工程图纸，不作施工依据</small><svg viewBox="0 0 700 170" aria-label="幕墙节点示意"><g fill="none" stroke="#6f9c8a" stroke-width="2"><path d="M30 45H670M30 65H670"/><path d="M120 65V150H145V65M335 65V150H360V65M550 65V150H575V65"/><path d="M145 90H335V145H145ZM360 90H550V145H360Z"/></g><rect x="315" y="40" width="65" height="115" fill="none" stroke="#c6974e" stroke-dasharray="5 5"/><text x="390" y="120" font-size="12" fill="#8b7957">关联测点与修订区域</text></svg></div><p class="quiet">首期支持成果附件查阅与版本管理，示意图不代表 CAD 自动解析能力。</p>${files(d.files)}${facts([['审核与发布依据',esc(d.basis)],['技术审核意见',esc(d.review||'初始化示例，详见关联业务记录')]])}${d.issue?`<div class="actions" style="margin-top:20px">${b('查看关联设计处置','issueDetail',d.issue,'primary')}</div>`:''}</div>`);}
function acceptance(){const rows=S.acceptances.filter(a=>S.filter==='all'||(S.filter==='pending'?a.status==='pending':a.status!=='pending'));return head('ACCEPTANCE CENTER','验收中心','独立接收申请，按批准要求核验；通过后才完成任务或关闭问题。')+`<div class="guide"><div><strong>验收由 PM 组织，按项目授权执行</strong><p>专业检查与必要签认须有对应记录。本原型演示 PM 验收，不代替正式工程验收。</p></div>${tag('独立验收记录','teal')}</div><div class="toolbar"><div class="filters">${[['all','全部申请'],['pending','待验收'],['history','已办理']].map(([v,l])=>`<button class="${S.filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div></div>`+card('验收申请',rows.map(a=>queue(a.title,(a.type==='issue'?'整改验收':'任务完工核验')+' · '+a.owner,'acceptDetail',a.id,'✓',status(a.status))).join('')||empty('暂无验收申请','请切换施工端，完成现场记录或整改后提交申请。'));}
function acceptDetail(id){const a=S.acceptances.find(x=>x.id===id);if(!a)return empty();const target=a.type==='issue'?S.issues.find(x=>x.id===a.target):S.tasks.find(x=>x.id===a.target);return b('← 返回验收中心','acceptancePage','','link detailback')+head('ACCEPTANCE / '+esc(a.id),esc(a.title),a.type==='issue'?'整改结果验收':'任务完工核验',status(a.status))+`<div class="detailgrid"><div>${card('验收依据',`<div class="cardbody">${facts([['关联对象',esc(a.target)],['验收负责人',esc(a.owner)],['批准要求',esc(a.criteria)],['现场位置',esc(target?.location)]])}${target?.plan?`<p>处置依据：${esc(target.plan)}</p>`:''}<div class="note">资料齐全不等于实体合格；按批准指标判断，不统一要求偏差“归零”。</div></div>`)}${card('提交结果与证据',a.submissions.map((r,n)=>`<div class="cardbody"><div class="row between"><h3>第 ${n+1} 次提交</h3><span class="quiet">${esc(r.time)}</span></div><p>${esc(r.text)}</p>${r.value?`<p>检查 / 复测结果：${esc(r.value)}</p>`:''}${files(r.files)}</div>`).join('')+`<div class="bottomaction">${S.role==='pm'&&a.status==='pending'?b('开始验收','accept',a.id,'primary'):'<span class="quiet">'+(a.status==='pending'?'等待授权 PM 组织验收':'已保存本次验收结论')+'</span>'}${b('查看原记录',a.type==='issue'?'issueDetail':'taskDetail',a.target)}</div>`)}</div><div>${card('历次验收意见',`<div class="cardbody">${a.reviews.length?a.reviews.map(r=>`<div class="event"><strong>${esc({pass:'通过',evidence:'补证据',rework:'退回整改',technical:'技术复核'}[r.result])}</strong><p>${esc(r.text)}</p><small>${esc(r.actor)} · ${esc(r.time)}</small></div>`).join(''):'<span class="quiet">尚未形成验收结论</span>'}</div>`)}</div></div>`;}
function surveys(){return Measurements.page();}
function risks(){const rows=S.issues.filter(i=>i.escalation);return head('MANAGEMENT ESCALATION','重大事项','资源决策与技术处置并行，知悉或批准预算不等于验收关闭。')+rows.map(i=>card(i.title,`<div class="cardbody"><div class="row">${status(i.escalation.status)}${status(i.status)}<span class="mono">${esc(i.id)}</span></div><h3 style="margin-top:18px">需要决定什么</h3><p>${esc(i.escalation.request)}</p>${i.escalation.decision?`<h3>管理决定</h3><p>${esc(i.escalation.decision)}</p><p class="quiet">资源 / 预算安排：${esc(i.escalation.budget||'未另列')}</p>`:''}${i.escalation.feedback?`<div class="note">落实反馈：${esc(i.escalation.feedback)}</div>`:''}<div class="actions">${S.role==='boss'&&i.escalation.status==='requested'?b('登记管理决策','decision',i.id,'primary'):''}${S.role==='pm'&&i.escalation.status==='decided'?b('反馈落实情况','implement',i.id,'primary'):''}${S.role!=='boss'?b('查看问题处理进展','issueDetail',i.id):''}</div></div>`)).join('')||empty('暂无重大事项');}
function messages(){return head('INBOX','消息与待办','确认阅读只表示接收信息，办理结果由业务状态决定。')+card('通知记录',S.messages.filter(m=>m.role===S.role).map(m=>`<div class="queueitem"><div class="queueicon">♧</div><div class="body"><div class="itemtitle">${esc(m.text)}</div><div class="quiet">${esc(m.time)} · ${esc(m.object)}</div></div>${m.read?tag('已读'):b('标为已读','read',m.id,'small')}</div>`).join('')||empty('暂无新消息','可以从今日待办直接处理已有任务。'));}
function records(){const closed=S.issues.filter(x=>x.status==='closed').length;return head('PROJECT RECORDS','记录与报告','仅汇总当前浏览器示例数据，结果与实际业务状态一致。',b('导出项目记录','export'))+`<div class="stats">${stat('任务总数',S.tasks.length,'试点示例')}${stat('问题总数',S.issues.length,'含未分流问题')}${stat('已关闭问题',closed,'具备本地验收通过记录')}${stat('操作记录',S.audit.length,'此原型中的角色操作')}</div>`+card('项目摘要',`<div class="cardbody"><p>当前 ${S.tasks.length} 项施工任务，${S.tasks.filter(t=>t.status==='complete').length} 项已完成；${S.issues.length} 项问题中 ${closed} 项已关闭，${S.issues.length-closed} 项仍在处理中。</p><p>验收中心当前待验收 ${S.acceptances.filter(a=>a.status==='pending').length} 项；重大管理事项 ${S.issues.filter(i=>i.escalation&&i.escalation.status!=='implemented').length} 项尚待决策或落实。</p><div class="policy">基于状态的确定性摘要，不模拟已接入大模型。导出文件包含完整示例业务记录与操作事件。</div></div>`)+card('操作留痕',timeline());}
function render(){if(S.role==='worker'){$('app').innerHTML=workerView();persist();return;}const menu=menus[S.role]||menus.pm;if(!menu.some(x=>x[0]===S.page))S.page=menu[0][0];const pages={overview,tasks,issues,drawings,acceptance,surveys,risks,messages,records};let body=S.detail?(S.detail.type==='issue'?issueDetail(S.detail.id):S.detail.type==='task'?taskDetail(S.detail.id):S.detail.type==='drawing'?drawingDetail(S.detail.id):acceptDetail(S.detail.id)):(pages[S.page]||overview)();const mobile=S.role==='worker'&&!S.detail;
$('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">匠</span><div>工程排障助手<small>BANGBANGJIANG</small></div></div><div class="navlabel">项目工作空间</div><nav class="nav">${menu.map(([p,icon,l])=>`<button data-page="${p}" class="${S.page===p?'active':''}"><span class="ico">${icon}</span>${l}${p==='acceptance'&&S.acceptances.some(a=>a.status==='pending')?`<span class="count">${S.acceptances.filter(a=>a.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="sidebarfoot"><span class="live-dot"></span>本地交互原型 v3<br><br>滨江商务中心 T2<br>东立面幕墙 · 试点工作空间<br><br><a href="legacy.html" style="color:#a9c2bb">查看旧版原型 ↗</a></div></aside><main class="main"><header class="topbar"><div class="crumb">项目 / <strong>滨江商务中心 T2</strong>　/　${menu.find(x=>x[0]===S.page)?.[2]||'工作台'}</div><div class="toptools"><span class="badge-role">演示角色</span><select id="role" aria-label="切换演示角色">${Object.entries(M.people).map(([v,l])=>`<option value="${v}" ${v===S.role?'selected':''}>${l}</option>`).join('')}</select><span class="avatar">${esc(M.people[S.role][0])}</span>${b('重置','reset','','small')}</div></header><div class="content"><div class="${mobile?'mobilepreview':''}">${body}${mobile?`<div class="mobilebar">${menus.worker.map(([p,icon,l])=>`<button data-page="${p}" class="${S.page===p?'active':''}">${icon} ${l}</button>`).join('')}</div>`:''}</div><div class="footerline"><span>帮帮匠 / 工程排障助手 · 任务驱动，异常分流，验收独立</span><span>示例数据 · 本机保存 · AI 为模板演示</span></div></div></main></div>`;persist();}

// Forms keep business inputs short and inherit existing associations.
const input=(name,label,value='',type='text',hint='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''}><small>${hint}</small></div>`;
const area=(name,label,value='',hint='')=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea><small>${hint}</small></div>`;
const select=(name,label,options,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const check=(name,label)=>`<div class="field"><label class="check"><input name="${name}" type="checkbox">${label}</label></div>`;
const upload=()=>`<div class="field"><label for="upload">上传附件</label><input id="upload" type="file" multiple accept="image/*,.pdf,.txt,.dwg"><small>本地演示：每份不超过 1 MB，最多 3 份。仅保存于当前浏览器，不上传服务器。</small><button type="button" class="small" data-action="sampleFile" style="margin-top:9px">使用示例附件（仅演示）</button><div id="uploadState" class="quiet"></div><div id="filePreview"></div></div>`;
const ai=()=>`<div class="ai"><strong>✧ 辅助整理 · 模板演示</strong><p>填入一段现场口述，演示提取数量和整理记录。未接入语音识别或大模型。</p><textarea id="aiSource" style="width:100%;border:1px solid #dddff0;border-radius:6px;padding:8px" placeholder="例如：今天东立面完成4块安装，节点照片已拍摄。"></textarea><button type="button" data-action="aiFill" style="margin-top:8px">整理到下方草稿</button></div>`;
function showModal(type,id=''){lastFocus=document.activeElement;modal={type,id};pendingFiles=[];const i=S.issues.find(x=>x.id===id),t=S.tasks.find(x=>x.id===id),a=S.acceptances.find(x=>x.id===id);let title='',body='',submit='确认提交';
switch(type){
case 'guide':title='三条业务路径';body=`<div class="routecards"><div class="routecard"><b>01 / 正常施工</b><p>接任务 → 记录与自检 → 提交完工 → 验收</p></div><div class="routecard"><b>02 / 普通整改</b><p>上报 → 明确批准依据 → 整改 → 独立验收</p></div><div class="routecard"><b>03 / 设计变更</b><p>上报 → 设计 → 总工审核 → PM发布 → 整改 → 验收</p></div></div><div class="note">建议演示：施工端处理 ISS-006 → PM 验收；设计端处理 ISS-018 → 总工审核 → PM 发布 → 施工整改。</div><p class="quiet">初始任务已签收开工；新派发的任务需施工端签收、确认开工。重大事项可切换授权决策人处理。</p>`;break;
case 'reset':title='重置演示数据';body='<p>将清除新版原型在此浏览器中的任务、附件、草稿和操作记录，恢复初始示例。旧版原型不受影响。</p>';submit='重置为初始示例';break;
case 'receive':title='签收施工任务';body=`<p>${esc(t?.title)}</p><div class="note">签收确认已接收任务与绑定图纸；下一步仍需确认开工条件。</div>`;break;
case 'start':title='确认本任务开工条件';body=check('confirm','已按本任务要求完成交底，核实人员、设备、必要作业审批及现场条件，当前无阻断事项。');break;
case 'updateTask':title='核对变更影响并更新任务';body=`<div class="note">${esc(t?.impact)}</div>`+check('confirm','已核对本任务适用范围、未施工与已施工部分的处理要求；更新后由班组重新签收。');break;
case 'log':title='记录施工进展';body=(S.role==='worker'?'':ai())+input('quantity','本次新增完成量（块）','0','number','剩余 '+(t.planned-t.done)+' 块；只填写本次新增量。')+area('text','施工内容与现场情况')+check('check','本次对应工序已完成自检，相关记录真实。')+upload();break;
case 'taskSubmit':title='申请任务完工核验';body=`<div class="note">验收要求：${esc(t?.checks)}</div>`+area('text','完工范围与检查说明')+check('check','本任务范围已完成，对应自检与必要资料已核对。')+upload();submit='提交至验收中心';break;
case 'report':if(S.role==='worker'){title='发现了什么问题？';body=VoiceDraft.panel()+area('text','描述现场问题','','写清位置、现象和影响；提交后由项目经理安排处理。')+`<section id="voiceReview" hidden><div class="note">请核对草稿：位置需与口述一致；数值未验证，不自动判断合格。</div>${input('impact','施工影响（未提及可留空）')}${input('measurement','口述数值与单位（请核对正负号）')}${select('valueKind','数值性质',[['unconfirmed','待确认'],['estimate','估计值'],['measured','实测值（需对应测量依据）']])}${check('voiceConfirmed','我已核对位置、数值、单位及事实，草稿与现场描述一致。')}</section>`+upload()+select('level','是否需要尽快处理',[['normal','一般问题'],['major','疑似重大，请尽快核实']])+`<details class="fieldfold"><summary>核对位置与任务（已带入）</summary>${select('task','关联任务',[['','独立现场问题'],...S.tasks.map(x=>[x.id,x.title])],t?.id||S.tasks[0]?.id)}${input('location','发生位置',t?.location||S.tasks[0]?.location||'')}</details>`;submit='提交问题';break;}title='上报现场问题';body=(S.role==='worker'?'':ai())+select('task','关联任务',[['','独立现场问题'],...S.tasks.map(x=>[x.id,x.title])],t?.id||S.tasks[0]?.id)+input('title','问题标题')+input('location','发生位置',t?.location||S.tasks[0]?.location||'')+area('text','现场事实与影响','','先记录事实；处置建议不自动成为执行依据。')+select('level','关注程度',[['normal','一般关注'],['major','疑似重大，需尽快核实']])+upload();break;
case 'triage':title='研判与分流';body=select('path','选择处理路径',[['normal','普通整改 · 已有明确批准依据'],['design','设计处置 · 需要新的技术依据'],['supplement','补测 / 澄清 · 事实尚不完整']],i.path||'normal')+select('level','人工核实关注等级',[['normal','一般问题'],['major','重大关注']],i.level)+input('due','办理期限',i.due||'2026-11-09','date')+area('text','处理要求 / 已批准依据',i.plan||i.request||'')+area('criteria','验收要求',i.criteria==='待批准方案明确对应测点及验收要求'?'':i.criteria,'普通整改需明确；设计分支由技术成果补齐。');break;
case 'supplement':title='补充问题卡说明';body=`<div class="note">${esc(i.request)}</div>`+area('text','补充说明','','已有测量结果请引用测量表编号与测点，无需重复上传整表。附件仅在确有新证据时补充。')+upload();break;
case 'requestSurvey':title='请求现场补测';body=area('text','具体测点、基准、资料要求','','发送给施工班组长；补充后返回当前设计任务。');break;
case 'design':title='提交设计处置成果';body=`<div class="note">原问题：${esc(i.title)}。此处提交待审成果，不直接下发施工。</div>`+input('rev','新修订号','REV-C-03')+area('text','技术处置说明与适用条件',i.plan)+area('criteria','整改检查与验收要求',i.criteria==='待批准方案明确对应测点及验收要求'?'':i.criteria)+upload();submit='提交总工审核';break;
case 'review':title='总工技术审核';body=`<p>${esc(i.title)}</p><div class="note">处置方案：${esc(i.plan)}</div>`+select('result','审核结论',[['pass','技术审核通过，交 PM 现场核对'],['return','退回设计修改']])+area('text','审核意见及必要会签依据','','本原型通过文字与附件记录必要会签，未模拟外部审批系统。');break;
case 'publish':title='现场核对与锁版发布';body=`<div class="note">发布版本：${esc(S.drawings.find(d=>d.id===i.newDrawing)?.rev)}。首期按同图号整体替代；系统将提示受影响任务。</div>`+check('confirm','已核对现场资料、成果适用范围、必要审核签认及替代影响。')+area('text','现场核对意见与影响说明');submit='发布并派发整改';break;
case 'rectify':title=i.status==='evidence'?'补充整改证据':'提交整改并申请验收';body=`<div class="note">执行依据：${esc(i.plan)}<br>验收要求：${esc(i.criteria)}</div>${i.returnReason?`<div class="note dangerNote">退回原因：${esc(i.returnReason)}</div>`:''}`+area('text','实际整改措施')+input('value','对应测点的复测 / 检查结果','','text','写明测点、数值、单位；外观类填写检查结果。')+check('check','已按批准依据完成整改、自检，提交内容与现场一致。')+upload();submit='提交至验收中心';break;
case 'accept':title='整改验收 / 完工核验';body=`<div class="note">验收要求：${esc(a.criteria)}</div>`+select('result','验收结论',[['pass','通过 · 必要检查及签认齐备'],['evidence','补充证据 · 当前无法判断'],['rework','退回整改 · 实体不符合要求'],['technical','技术复核 · 原方案不适用']])+area('text','结论依据 / 指定退回要求','','通过需写明检查依据，退回需明确补什么或改什么。')+check('confirm','通过前确认：已完成必要现场检查、专业检测及相应签认，并核对记录。');submit='保存验收结论';break;
case 'dispatch':title='派发施工任务';body=input('title','任务名称')+input('location','工作位置','3号楼 / 12F / 东立面')+input('scope','构件 / 批次范围')+select('drawing','执行图纸',S.drawings.filter(d=>d.status==='effective').map(d=>[d.id,d.number+' · '+d.rev]))+`<div class="two">${input('quantity','计划量（块）','8','number')}${input('due','完成期限','2026-11-09','date')}</div>`+area('criteria','检查与验收要求','','明确检查对象、必要实测或照片要求。');break;
case 'survey':title='基层多测点测量表';body=Measurements.form(id);submit='整表提交核验';break;
case 'verifySurvey':title='现场资料核验';body='<div class="note">只判断资料是否可用；超差不因资料完整而变为合格。</div>'+select('result','核验结论',[['pass','资料可用'],['return','退回补充']])+area('text','核验依据 / 补充要求');break;
case 'escalate':title='升级重大事项';body=area('text','影响、当前措施与需要决策的事项','','技术处置并行推进；紧急情况按项目机制先控制、先报告。');break;
case 'decision':title='登记管理决策';body=`<div class="note">${esc(i.escalation.request)}</div>`+area('text','资源、优先级、协调负责人及期限')+input('budget','资源 / 预算安排（选填）')+'<div class="policy">管理决定不代替技术审批、现场开工许可和质量验收。</div>';break;
case 'implement':title='反馈管理决策落实';body=area('text','落实结果与遗留事项');break;
default:return;
}
const draft=S.drafts[type+':'+id];$('overlay').innerHTML=`<div class="modalshade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><form id="form"><div class="modalhead"><h2 id="modalTitle">${title}</h2><button type="button" class="link" data-action="close" aria-label="关闭">✕</button></div><div class="modalbody"><div id="formError" role="alert"></div>${draft?'<div class="note">已恢复上次保存的文字草稿；附件请重新选择。</div>':''}${body}</div><div class="modalfoot">${!['guide','reset'].includes(type)?'<button type="button" data-action="saveDraft">保存草稿</button>':''}<button type="button" data-action="close">${type==='guide'?'知道了':'取消'}</button>${type!=='guide'?`<button class="primary" type="submit">${submit}</button>`:''}</div></form></section></div>`;
if(draft){for(const el of $('form').elements){if(el.name&&draft[el.name]!==undefined){if(el.type==='checkbox')el.checked=!!draft[el.name];else el.value=draft[el.name];}}}
$('form').addEventListener('submit',submitForm);if(type==='report'&&S.role==='worker')VoiceDraft.init();setTimeout(()=>$('overlay').querySelector('input,textarea,select,button')?.focus(),0);}
function values(){const f=$('form'),p={id:modal.id,files:pendingFiles};for(const el of f.elements){if(el.name)p[el.name]=el.type==='checkbox'?el.checked:el.value.trim();}if(modal.type==='report'&&S.role==='worker')p.title=p.text?.slice(0,40)||'';return p;}
function closeModal(){VoiceDraft.close();modal=null;$('overlay').innerHTML='';lastFocus?.focus();}
function submitForm(e){e.preventDefault();if(modal.uploading){$('formError').innerHTML='<div class="error">附件正在读取，请稍候再提交。</div>';return;}const {type,id}=modal;
if(type==='reset'){S=M.seed();persist();closeModal();render();toast('已恢复初始示例');return;}
try{const payload=type==='survey'?Measurements.payload():values();if(type==='report'&&S.role==='worker')VoiceDraft.collect(payload);const next=M.apply(S,type==='survey'?'submitMeasurements':type,payload);delete next.drafts[type+':'+id];S=next;if(type==='survey'){S.page='surveys';S.detail=null;}persist();closeModal();render();toast('已提交，下一步待办已更新');}catch(err){$('formError').innerHTML=`<div class="error">${esc(err.message)}</div>`;$('formError').scrollIntoView({block:'nearest'});}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){nav(p.dataset.page);return;}const f=e.target.closest('[data-filter]');if(f){S.filter=f.dataset.filter;render();return;}const x=e.target.closest('[data-action]');if(!x)return;const action=x.dataset.action,id=x.dataset.id;if(Measurements.handle(action,id,x))return;
if(action==='close'){closeModal();return;}if(action==='saveDraft'){const v=values();delete v.files;S.drafts[modal.type+':'+modal.id]=v;persist();toast('文字草稿已保存在本机；附件需重新选择');return;}
if(action==='sampleFile'){pendingFiles=[{name:'演示证据-非现场实拍.txt',size:27,image:false,data:'data:text/plain;base64,RGVtbyBldmlkZW5jZSBvbmx5LCBub3QgcmVhbCBmaWVsZCBkYXRhLg=='}];$('uploadState').textContent='已选择演示附件，不代表真实现场证据。';$('filePreview').innerHTML=files(pendingFiles);return;}
if(action==='aiFill'){const text=$('aiSource').value.trim();if(!text){toast('请先填写示例口述内容');return;}$('f-text').value=text;const match=text.match(/(\d+)\s*块/);if(match&&$('f-quantity'))$('f-quantity').value=match[1];toast('已填入可编辑草稿，请核对事实、数量和位置');return;}
if(action==='export'){const blob=new Blob([JSON.stringify({...S,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='工程排障助手-演示记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
if(action==='read'){const m=S.messages.find(z=>z.id===id);if(m)m.read=true;render();return;}
if(action.endsWith('Page')){nav(action.replace('Page',''));return;}if(action.endsWith('Detail')){openDetail({issueDetail:'issue',taskDetail:'task',drawingDetail:'drawing',acceptDetail:'accept'}[action],id);return;}showModal(action,id);});
document.addEventListener('change',async e=>{if(e.target.id==='role'){S.role=e.target.value;S.detail=null;S.page=S.role==='boss'?'risks':'overview';S.filter='all';S.search='';render();return;}if(e.target.id==='upload'&&modal){const selected=[...e.target.files];pendingFiles=[];if(selected.length>3||selected.some(f=>f.size>1024*1024)){e.target.value='';$('uploadState').textContent='选择失败：最多 3 份，每份不超过 1 MB，请重新选择。';$('filePreview').innerHTML='';return;}const current=modal;current.uploading=true;$('uploadState').textContent='正在读取本地附件…';try{const results=await Promise.all(selected.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,size:f.size,image:f.type.startsWith('image/'),data:reader.result});reader.onerror=()=>reject(Error('附件读取失败，请重新选择'));reader.readAsDataURL(f);})));if(modal!==current)return;pendingFiles=results;$('uploadState').textContent='本地读取成功：'+results.length+' 份。尚未提交业务记录。';$('filePreview').innerHTML=files(results);}catch(err){if(modal===current)$('uploadState').textContent=err.message;}finally{current.uploading=false;}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){S.search=e.target.value;const pos=e.target.selectionStart;render();$('search')?.focus();$('search')?.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...$('overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();
